170		}
171		// 另一个同样处于执行中的批次 B2，绑定同一配方版本，使“改批次”的
172		// 提交本身也是一笔合法投料。
173		if _, err := s.CreateBatch("b2", "B2", "R1", "v1", 5); err != nil {
174			t.Fatalf("创建 B2 失败: %v", err)
175		}
