236		// 全部冲突之后，原内容用原编号仍取得第一次成功结果，不是最近一笔。
237		replay, err := s.AddFeeding("feed-orig", "B1", "M1", "10", t1, "张三")
238		if err != nil {
239			t.Fatalf("冲突后原内容重放应成功: %v", err)
240		}
