412		checkFeedingView(t, independent, 2, "M1", "1", t1, "张三")
413	
414		// 批次现有两笔，登记顺序与各自内容清晰；只增加 M1 的实投（1+1=2），
415		// M2、M3 仍为零。
416		view := mustGetBatch(t, s, "B1")
417		if len(view.Feedings) != 2 {
418			t.Fatalf("应追加为 2 条投料，得到 %d 条: %+v", len(view.Feedings), view.Feedings)
419		}
420		checkFeedingView(t, &view.Feedings[0], 1, "M1", "1", t1, "张三")
421		checkFeedingView(t, &view.Feedings[1], 2, "M1", "1", t1, "张三")
422		mats := materialsMap(view)
423		checkRequirement(t, mats, "M1", "1000", "2", "-998")
424		checkRequirement(t, mats, "M2", "5", "0", "-5")
425		checkRequirement(t, mats, "M3", "0.1", "0", "-0.1")
426	
427		// 新投料追加后，原编号的重放结果必须仍是第一次那笔（序号 1），
428		// 不能把后来同内容的序号 2 误当成原记录。
429		replayAgain, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", t1, "张三")
430		if err != nil {
431			t.Fatalf("追加同内容投料后原编号重放应成功: %v", err)
432		}
433		checkFeedingView(t, replayAgain, 1, "M1", "1", t1, "张三")
434		// 新编号重放的是它自己的第一次结果（序号 2），两者各自独立。
435		replayNew, err := s.AddFeeding("feed-2", "B1", "M1", "1.000", t1, "张三")
436		if err != nil {
437			t.Fatalf("新编号重放应成功: %v", err)
438		}
439		checkFeedingView(t, replayNew, 2, "M1", "1", t1, "张三")
440	
441		// 两次重放都不重复计入：仍是 2 条、M1 累计 2。
442		view = mustGetBatch(t, s, "B1")
443		if len(view.Feedings) != 2 {
444			t.Fatalf("重放不应新增投料，得到 %d 条", len(view.Feedings))
445		}
446		mats = materialsMap(view)
447		checkRequirement(t, mats, "M1", "1000", "2", "-998")
448	}
