756			t.Fatalf("位置 2 不应看到位置 1 的批次，得到 %v", err)
757		}
758	
759		// 两个位置可以各自使用相同的请求编号而互不影响。
760		if _, err := s2.RegisterRecipe("r1", "R1", "v1", "另一个配方", []MaterialInput{
761			{MaterialNo: "M2", Grams: "2"},
762		}); err != nil {
763			t.Fatalf("不同位置应独立登记: %v", err)
764		}
765		r1, _ := s1.GetRecipe("R1", "v1")
766		r2, _ := s2.GetRecipe("R1", "v1")
767		if r1.Name == r2.Name {
768			t.Fatalf("两个位置的同名配方不应互相影响")
769		}
770	}
771	
772	// 已有数据损坏时明确报错，不能当成空台账继续。
773	func TestCorruptData(t *testing.T) {
774		dir := t.TempDir()
775		// 先写入有效数据。
776		s, err := Open(dir)
777		if err != nil {
778			t.Fatal(err)
779		}
780		if _, err := s.RegisterRecipe("r1", "R1", "v1", "配方一", []MaterialInput{
781			{MaterialNo: "M1", Grams: "1"},
782		}); err != nil {
783			t.Fatal(err)
784		}
785		s.Close()
786	
787		// 破坏台账文件。
788		if err := os.WriteFile(filepath.Join(dir, "ledger.json"), []byte("{不是合法JSON"), 0o644); err != nil {
789			t.Fatal(err)
790		}
791		if _, err := Open(dir); !errors.Is(err, ErrCorruptData) {
792			t.Fatalf("损坏数据应返回 ErrCorruptData，得到 %v", err)
793		}
794	
795		// 合法 JSON 但版本不受支持。
796		if err := os.WriteFile(filepath.Join(dir, "ledger.json"), []byte(`{"version":99,"recipes":[],"batches":[],"requests":{}}`), 0o644); err != nil {
797			t.Fatal(err)
798		}
799		if _, err := Open(dir); !errors.Is(err, ErrCorruptData) {
800			t.Fatalf("不支持的版本应返回 ErrCorruptData，得到 %v", err)
801		}
802	
803		// 空文件不等于“没有台账文件”，按损坏处理，不能当成空台账。
804		if err := os.WriteFile(filepath.Join(dir, "ledger.json"), []byte{}, 0o644); err != nil {
805			t.Fatal(err)
806		}
807		s2, err := Open(dir)
808		if !errors.Is(err, ErrCorruptData) {
809			t.Fatalf("零字节台账应返回 ErrCorruptData，得到 %v", err)
810		}
811		if s2 != nil {
812			s2.Close()
813			t.Fatalf("损坏台账不应返回可用的 Store 对象")
814		}
815		if !strings.Contains(err.Error(), "没有内容") {
816			t.Fatalf("错误信息应说明台账文件没有内容，得到 %v", err)
817		}
818	}
819	
820	// 跨进程并发：两个进程同时向同一台账投料，数据不互相覆盖。
821	// 本子进程由 TestCrossProcessConcurrent 通过环境变量驱动。
822	func TestHelperProcess(t *testing.T) {
823		if os.Getenv("HELPER_PROCESS") != "1" {
824			return
825		}
826		dir := os.Getenv("HELPER_DIR")
827		id := os.Getenv("HELPER_ID")
828		s, err := Open(dir)
829		if err != nil {
830			fmt.Fprintf(os.Stderr, "helper open: %v\n", err)
831			os.Exit(1)
832		}
833		defer s.Close()
834		for i := 0; i < 20; i++ {
835			if _, err := s.AddFeeding(fmt.Sprintf("f-%s-%03d", id, i), "B1", "M1", "1",
836				time.Now(), "登记人"+id); err != nil {
837				fmt.Fprintf(os.Stderr, "helper feed: %v\n", err)
838				os.Exit(1)
839			}
840		}
841		os.Exit(0)
842	}
843	
844	func TestCrossProcessConcurrent(t *testing.T) {
845		dir := t.TempDir()
846		// 父进程先登记配方，避免与子进程的登记请求竞争同一版本。
847		s, err := Open(dir)
848		if err != nil {
849			t.Fatal(err)
850		}
851		if _, err := s.RegisterRecipe("recipe-parent", "R1", "v1", "配方一", []MaterialInput{
852			{MaterialNo: "M1", Grams: "1"},
853		}); err != nil {
854			t.Fatal(err)
855		}
856		if _, err := s.CreateBatch("b-parent", "B1", "R1", "v1", 10); err != nil {
857			t.Fatal(err)
858		}
859		if _, err := s.StartBatch("s-parent", "B1"); err != nil {
860			t.Fatal(err)
861		}
862		s.Close()
863	
864		runHelper := func(id string) error {
865			cmd := exec.Command(os.Args[0], "-test.run=TestHelperProcess")
866			cmd.Env = append(os.Environ(),
867				"HELPER_PROCESS=1",
868				"HELPER_DIR="+dir,
869				"HELPER_ID="+id,
870			)
871			out, err := cmd.CombinedOutput()
872			if err != nil {
873				return fmt.Errorf("%v: %s", err, out)
874			}
875			return nil
876		}
877	
878		var wg sync.WaitGroup
879		errs := make(chan error, 2)
880		for _, id := range []string{"A", "B"} {
881			wg.Add(1)
882			go func(id string) {
883				defer wg.Done()
884				errs <- runHelper(id)
885			}(id)
886		}
887		wg.Wait()
888		close(errs)
889		for err := range errs {
890			if err != nil {
891				t.Fatalf("子进程失败: %v", err)
892			}
893		}
894	
895		s2, err := Open(dir)
896		if err != nil {
897			t.Fatal(err)
898		}
899		defer s2.Close()
900		got, err := s2.GetBatch("B1")
901		if err != nil {
902			t.Fatal(err)
903		}
904		if len(got.Feedings) != 40 {
905			t.Fatalf("两个进程共应登记 40 条投料，得到 %d 条（数据被覆盖）", len(got.Feedings))
906		}
907		seqs := map[int]bool{}
908		for _, f := range got.Feedings {
909			if seqs[f.Seq] {
910				t.Fatalf("投料序号重复: %d", f.Seq)
911			}
912			seqs[f.Seq] = true
913		}
914		if got.Materials[0].ActualGrams != "40" {
915			t.Fatalf("累计实投应为 40，得到 %s", got.Materials[0].ActualGrams)
916		}
917	}
918	
919	// 克数精度：三位小数精确计算，不丢精度。
920	func TestGramsPrecision(t *testing.T) {
921		s := openTestStore(t)
922		if _, err := s.RegisterRecipe("r1", "R1", "v1", "精度配方", []MaterialInput{
923			{MaterialNo: "M1", Grams: "0.001"},
924			{MaterialNo: "M2", Grams: "100.123"},
925		}); err != nil {
926			t.Fatal(err)
927		}
928		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 3); err != nil {
929			t.Fatal(err)
930		}
931		if _, err := s.StartBatch("s1", "B1"); err != nil {
932			t.Fatal(err)
933		}
934		// 0.001 + 0.002 = 0.003（浮点下 0.001+0.002 != 0.003）。
935		if _, err := s.AddFeeding("f1", "B1", "M1", "0.001", time.Now(), "张三"); err != nil {
936			t.Fatal(err)
937		}
938		if _, err := s.AddFeeding("f2", "B1", "M1", "0.002", time.Now(), "张三"); err != nil {
939			t.Fatal(err)
940		}
941		got, err := s.GetBatch("B1")
942		if err != nil {
943			t.Fatal(err)
944		}
945		m := map[string]MaterialRequirement{}
946		for _, mm := range got.Materials {
947			m[mm.MaterialNo] = mm
948		}
949		if m["M1"].RequiredGrams != "0.003" || m["M1"].ActualGrams != "0.003" || m["M1"].DifferenceGrams != "0" {
950			t.Fatalf("M1 数量核对不正确: %+v", m["M1"])
951		}
952		if m["M2"].RequiredGrams != "300.369" {
953			t.Fatalf("M2 应投量不正确: %+v", m["M2"])
954		}
955	}
